    if isinstance(result, dict):
        result.pop('header', None)
        d = result.get('data')
        if not isinstance(d, dict):
            d = {'ok': False, 'error': 'no response'}
            result['data'] = d
        ok = d.get('ok') is True or str(d.get('ok')).lower() == 'true'
        pid = ''
        fails = None
        try:
            pid = str(vars.get('cp_last_pid') or '')
        except Exception:
            pid = ''
        if ok:
            try:
                vars['promise_recorded'] = 'yes'
            except Exception:
                pass
            d['what_to_do_next'] = 'RECORDED' + (' for ' + pid if pid else '') + '. This promise is recorded. If other confirmed promises are still to be recorded, call create_promise for the next one now. When all are done, tell the customer the promise is recorded and say: "You will receive a text message confirming this promise."'
        else:
            try:
                k = 'cp_fail_' + pid
                fails = int(vars.get(k) or 0) + 1
                vars[k] = fails
            except Exception:
                fails = None
            if fails is not None and fails >= 2:
                d['what_to_do_next'] = 'NOT RECORDED' + (' for ' + pid if pid else '') + ' (second failure for this product). Do not try again. Tell the customer you could not record the promise for this product. Never say it is recorded. This product counts as a product without a promise with reason service_error (add_note at the end, unless a transfer happens).'
            elif fails == 1:
                d['what_to_do_next'] = 'NOT RECORDED' + (' for ' + pid if pid else '') + ' (first failure). Do not tell the customer it is recorded. Call create_promise once more right now with exactly the same product_id, amount and date.'
            else:
                d['what_to_do_next'] = 'NOT RECORDED. Do not tell the customer it is recorded. If this is the first failure for this product, call create_promise once more with the same values; if it already failed once, tell the customer you could not record it.'
except Exception:
    pass
'''

NOTE_PRE = r'''
try:
    b = config.get('body')
    if isinstance(b, dict):
        log = str(vars.get('notes_log') or '')
        vars['notes_log'] = log + str(b.get('product_id')) + ':' + str(b.get('reason')) + ';'
except Exception:
    pass
'''
SIMPLE_POST = r'''
try:
    if isinstance(result, dict):
        result.pop('header', None)
        d = result.get('data')
        if isinstance(d, dict):
            ok = d.get('ok') is True or str(d.get('ok')).lower() == 'true'
            d['what_to_do_next'] = (OKMSG if ok else FAILMSG)
except Exception:
    pass
'''


def simple_post(okmsg, failmsg):
    return 'OKMSG = ' + json.dumps(okmsg) + '\nFAILMSG = ' + json.dumps(failmsg) + '\n' + SIMPLE_POST


CLOSE_PRE = r'''
try:
    b = config.get('body')
    if isinstance(b, dict):
        qmap = {'restructuring': 'restructuring', 'support': 'support', 'general': 'human'}
        q = None
        try:
            if int(vars.get('transfer_to_agent_success_count') or 0) > 0:
                q = str(vars.get('transfer_to_agent_args.queue') or '')
        except Exception:
            q = None
        if q in qmap:
            b['outcome'] = 'transferred'
            b['reason'] = qmap[q]
        elif str(vars.get('promise_recorded') or '') == 'yes':
            b['outcome'] = 'promise'
        elif b.get('outcome') in ('no_promise', 'paid', 'promise'):
            log = str(vars.get('notes_log') or '')
            notes = {}
            for part in log.split(';'):
                if ':' in part:
                    pid, r = part.split(':', 1)
                    if pid not in notes:
                        notes[pid] = r
            order = []
            try:
                order = [str(p.get('product_id')) for p in json.loads(vars.get('products_json') or '[]')]
            except Exception:
                order = []
            if notes and order and all(p in notes for p in order):
                rs = [notes[p] for p in order]
                if all(r == 'paid' for r in rs):
                    b['outcome'] = 'paid'
                else:
                    b['outcome'] = 'no_promise'
                    b['reason'] = [r for r in rs if r != 'paid'][0]
        if b.get('outcome') in ('promise', 'paid'):
            b.pop('reason', None)
except Exception:
    pass
'''
